// ============================================================
// Node:    validate-and-sanitize-input
// Purpose: Sanitize and validate all user input before it
//          reaches the AI layer. Nothing passes through
//          without being checked here first.
// Version: 1.0
// Phase:   1 — Foundation
// ============================================================

const MAX_LENGTH = 4000;
const MIN_LENGTH = 10;

// ── Step 1: Pull the raw input from the webhook body ────────
// We expect the caller to send { "text": "..." }
// If the field is missing, rawInput becomes an empty string
const rawInput = $input.first().json?.body?.text || "";

// ── Step 2: Type check ──────────────────────────────────────
if (typeof rawInput !== "string") {
  throw new Error("VALIDATION_FAILED: Input must be a string");
}

// ── Step 3: Length checks ───────────────────────────────────
if (rawInput.trim().length < MIN_LENGTH) {
  throw new Error(
    `VALIDATION_FAILED: Input too short. Minimum is ${MIN_LENGTH} characters.`
  );
}

if (rawInput.length > MAX_LENGTH) {
  throw new Error(
    `VALIDATION_FAILED: Input too long. Maximum is ${MAX_LENGTH} characters.`
  );
}

// ── Step 4: Strip HTML tags ─────────────────────────────────
// Removes anything like <script>, <b>, <img src=...> etc.
const stripHtml = (str) => str.replace(/<[^>]*>/g, "");

// ── Step 5: Block prompt injection patterns ─────────────────
// These phrases are common attempts to hijack the AI system prompt.
// If detected, we reject the input before it ever reaches the model.
const blockPatterns = [
  /ignore previous instructions/i,
  /forget your instructions/i,
  /you are now/i,
  /disregard all/i,
  /system prompt/i,
  /override your/i,
  /act as if/i,
  /pretend you are/i,
];

for (const pattern of blockPatterns) {
  if (pattern.test(rawInput)) {
    throw new Error(
      "VALIDATION_FAILED: Input contains disallowed content"
    );
  }
}

// ── Step 6: Clean the input ─────────────────────────────────
const cleanedInput = stripHtml(rawInput).trim();

// ── Step 7: Return structured output ────────────────────────
// This object flows into the next node.
// Every field here is intentional:
//   clean_text  → what the AI will actually receive
//   run_id      → unique ID that tracks this request through the entire pipeline
//   received_at → UTC timestamp for the audit trail
//   char_count  → useful for logging and debugging
return [{
  json: {
    validated: true,
    clean_text: cleanedInput,
    char_count: cleanedInput.length,
    received_at: new Date().toISOString(),
    run_id: 'run-' + Date.now() + '-' + Math.random().toString(36).substring(2, 9),
  }
}];

